Solution B: function flightSimulator(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    canvas.width = 500;
    canvas.height = 500;

    // ==== Simulation State ====
    const state = {
        // Position (meters)
        x: 0,
        y: 0,
        z: 1000, // altitude in meters
        // Motion
        speed: 70, // m/s (~250 km/h)
        heading: 0, // degrees, 0 = north
        pitch: 0, // degrees
        roll: 0, // degrees
        yawRate: 0, // degrees per second
        // Controls
        throttle: 0.5, // 0..1
        // Resources
        fuel: 100, // percent
        // Time
        lastTime: performance.now(),
        // Instrument display values (may lag)
        display: {
            speed: 70,
            altitude: 1000,
            heading: 0
        },
        // Bug flags for visual indicators
        bug: {
            instrumentLag: false,
            altimeterSticky: false,
            compassAnomaly: false,
            engineFluctuation: false
        }
    };

    // ==== Input handling ====
    const keys = {};
    window.addEventListener('keydown', e => { keys[e.code] = true; });
    window.addEventListener('keyup', e => { keys[e.code] = false; });

    // ==== Helper functions ====
    function degToRad(d) { return d * Math.PI / 180; }
    function radToDeg(r) { return r * 180 / Math.PI; }

    // Simple terrain generator (height map)
    const terrain = [];
    const terrainCols = 200;
    const terrainRows = 200;
    for (let i = 0; i < terrainRows; i++) {
        terrain[i] = [];
        for (let j = 0; j < terrainCols; j++) {
            terrain[i][j] = Math.random() * 200; // height in meters
        }
    }

    // ==== Main Loop ====
    function loop(now) {
        const dt = (now - state.lastTime) / 1000; // seconds
        state.lastTime = now;
        updatePhysics(dt);
        render();
        requestAnimationFrame(loop);
    }

    // ==== Physics & Bug logic ====
    function updatePhysics(dt) {
        // ---- Controls ----
        // Throttle up/down
        if (keys['KeyW']) state.throttle = Math.min(1, state.throttle + dt * 0.2);
        if (keys['KeyS']) state.throttle = Math.max(0, state.throttle - dt * 0.2);
        // Pitch control
        if (keys['ArrowUp']) state.pitch = Math.max(-15, state.pitch - dt * 10);
        else if (keys['ArrowDown']) state.pitch = Math.min(15, state.pitch + dt * 10);
        else state.pitch *= 0.95; // auto level
        // Roll control
        if (keys['ArrowLeft']) state.roll = Math.max(-45, state.roll - dt * 30);
        else if (keys['ArrowRight']) state.roll = Math.min(45, state.roll + dt * 30);
        else state.roll *= 0.90;
        // Yaw (heading) control via A/D
        if (keys['KeyA']) state.heading = (state.heading - dt * 30 + 360) % 360;
        if (keys['KeyD']) state.heading = (state.heading + dt * 30) % 360;

        // ---- Engine thrust & intentional bug: power fluctuation during steep climbs ----
        const baseThrust = state.throttle * 20000; // Newtons
        let thrust = baseThrust;
        if (Math.abs(state.pitch) > 10 && state.throttle > 0.7) {
            // Intentional bug: engine power fluctuates under steep climb
            thrust += (Math.random() - 0.5) * 4000;
            state.bug.engineFluctuation = true;
        } else {
            state.bug.engineFluctuation = false;
        }

        // Simple drag
        const drag = 0.5 * 1.225 * 2.2 * Math.pow(state.speed, 2);
        const netForce = thrust - drag;
        const acceleration = netForce / 1500; // mass ~1500kg

        // Update speed, enforce minimum
        state.speed = Math.max(30, state.speed + acceleration * dt);

        // Update position (ignoring earth curvature for simplicity)
        const forward = degToRad(state.heading);
        state.x += Math.sin(forward) * state.speed * dt;
        state.y += Math.cos(forward) * state.speed * dt;
        // Update altitude based on pitch
        state.z += Math.sin(degToRad(state.pitch)) * state.speed * dt;
        if (state.z < 0) state.z = 0;
        if (state.z > 12000) state.z = 12000;

        // Fuel consumption proportional to throttle
        state.fuel -= state.throttle * dt * 0.5;
        if (state.fuel < 0) state.fuel = 0;

        // ---- G-force calculation (simple) ----
        const verticalAcc = Math.sin(degToRad(state.pitch)) * state.speed / 9.81; // g's from climb
        const gForce = Math.abs(1 + verticalAcc);
        // Intentional bug: instrument lag under high G
        if (gForce > 2) {
            // Apply lag: display values catch up slowly
            state.display.speed += (state.speed - state.display.speed) * 0.02;
            state.display.altitude += (state.z - state.display.altitude) * 0.02;
            state.display.heading += (state.heading - state.display.heading) * 0.02;
            state.bug.instrumentLag = true;
        } else {
            // No lag: display updates instantly
            state.display.speed = state.speed;
            state.display.altitude = state.z;
            state.display.heading = state.heading;
            state.bug.instrumentLag = false;
        }

        // ---- Altimeter stickiness bug at every 1000m ----
        const altMod = Math.floor(state.display.altitude / 1000) * 1000;
        if (Math.abs(state.display.altitude - altMod) < 5 && Math.random() < 0.01) {
            // Stick: hold altitude reading for a short time
            state.display.altitude = altMod;
            state.bug.altimeterSticky = true;
        } else {
            state.bug.altimeterSticky = false;
        }

        // ---- Compass deviation near magnetic anomalies ----
        // Define anomaly around heading 90° +/- 10°
        const diff = Math.min(Math.abs(state.heading - 90), 360 - Math.abs(state.heading - 90));
        if (diff < 10) {
            // Intentional bug: heading deviates up to +/-5°
            const deviation = (Math.random() - 0.5) * 10;
            state.display.heading = (state.heading + deviation + 360) % 360;
            state.bug.compassAnomaly = true;
        } else {
            state.display.heading = state.heading;
            state.bug.compassAnomaly = false;
        }
    }

    // ==== Rendering ====
    function render() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        drawSkyAndHorizon();
        drawTerrain();
        drawHUD();
        drawBugIndicators();
    }

    function drawSkyAndHorizon() {
        // Sky
        ctx.fillStyle = '#87CEEB';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        // Horizon line moves with pitch
        const horizonY = canvas.height / 2 - state.pitch * 5; // arbitrary scaling
        ctx.strokeStyle = '#654321';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, horizonY);
        ctx.lineTo(canvas.width, horizonY);
        ctx.stroke();
    }

    function drawTerrain() {
        // Simple flat terrain with random hills projected forward
        const scale = 200; // controls perspective strength
        ctx.fillStyle = '#228B22';
        for (let i = 0; i < terrainRows; i++) {
            const depth = i * 5; // meters forward
            const perspective = scale / (depth + scale);
            const terrainHeight = terrain[i][Math.floor(state.x) % terrainCols] - state.z;
            const y = canvas.height / 2 + terrainHeight * perspective + state.pitch * 5;
            const w = canvas.width * perspective;
            const h = canvas.height * perspective;
            ctx.fillRect((canvas.width - w) / 2, y, w, h);
        }
    }

    function drawHUD() {
        ctx.fillStyle = '#FFFFFF';
        ctx.font = '14px monospace';
        // Speed
        ctx.fillText(`SPD: ${Math.round(state.display.speed)} m/s`, 10, 20);
        // Altitude
        ctx.fillText(`ALT: ${Math.round(state.display.altitude)} m`, 10, 40);
        // Heading
        ctx.fillText(`HDG: ${Math.round(state.display.heading)}°`, 10, 60);
        // Fuel
        ctx.fillText(`FUEL: ${Math.round(state.fuel)}%`, 10, 80);
    }

    function drawBugIndicators() {
        // Red icons appear when a bug is active
        ctx.fillStyle = 'rgba(255,0,0,0.8)';
        ctx.font = '20px monospace';
        let x = canvas.width - 30;
        const yStart = 30;
        const step = 30;
        if (state.bug.instrumentLag) {
            ctx.fillText('⨂', x, yStart);
            x -= step;
        }
        if (state.bug.altimeterSticky) {
            ctx.fillText('⌛', x, yStart);
            x -= step;
        }
        if (state.bug.compassAnomaly) {
            ctx.fillText('🧭', x, yStart);
            x -= step;
        }
        if (state.bug.engineFluctuation) {
            ctx.fillText('⚡', x, yStart);
            // x -= step;
        }
    }

    // ==== Start the simulation ====
    requestAnimationFrame(loop);
}

